import random

def ask_int(prompt):
    while True:
        try:
            return int(input(prompt))
        except ValueError:
            print("numbers only, please")

def play():
    secret = random.randint(1, 100)
    guesses = 0
    while True:
        guess = ask_int("guess: ")
        guesses += 1
        if guess < secret:
            print("higher")
        elif guess > secret:
            print("lower")
        else:
            print(f"nice, {guesses} tries")
            return guesses

def load_best():
    try:
        with open("best.txt") as f:
            return int(f.read())
    except FileNotFoundError:
        return None

def save_best(score):
    with open("best.txt", "w") as f:
        f.write(str(score))

def main():
    print("guess my number, 1 to 100")
    score = play()
    best = load_best()
    if best is None or score < best:
        print("a new best score!")
        save_best(score)
    else:
        print(f"best to beat: {best}")

if __name__ == "__main__":
    main()
